import java.util.*;

class Solution {
    public int maxCoins(int[] coins) {
        int n = coins.length;
        if (n == 1) return coins[0];
        return Math.max(line(coins, 0, n - 2), line(coins, 1, n - 1));
    }

    // best sum on coins[lo..hi] with no two adjacent picks
    private int line(int[] c, int lo, int hi) {
        int take = 0, skip = 0;
        for (int i = lo; i <= hi; i++) {
            int newTake = skip + c[i];        // take this stall: previous must be skipped
            skip = Math.max(skip, take);
            take = newTake;
        }
        return Math.max(take, skip);
    }
}

