class Solution:
    def maxCoins(self, coins: List[int]) -> int:
        def line(a):
            x = y = 0
            for v in a: x, y = y, max(y, x + v)
            return y
        if len(coins) == 1: return coins[0]
        return max(line(coins[:-1]), line(coins[1:]))

