function maxCoins(coins) {
  const line = (a) => { let x = 0, y = 0; for (const v of a) [x, y] = [y, Math.max(y, x + v)]; return y; };
  if (coins.length === 1) return coins[0];
  return Math.max(line(coins.slice(0, -1)), line(coins.slice(1)));
}
